Here is the commit message:
net: Fix vti use case with oif in dst lookups

Steffen reported that the recent change to add oif to dst lookups breaks
the VTI use case. The problem is that with the oif set in the flow struct
the comparison to the nh_oif is triggered. Fix by splitting the
FLOWI_FLAG_VRFSRC into 2 flags -- one that triggers the vrf device cache
bypass (FLOWI_FLAG_VRFSRC) and another telling the lookup to not compare
nh oif (FLOWI_FLAG_SKIP_NH_OIF).

Fixes: 42a7b32b73d6 ("xfrm: Add oif to dst lookups")

Signed-off-by: David Ahern <dsa@cumulusnetworks.com>
Acked-by: Steffen Klassert <steffen.klassert@secunet.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The root cause of the bug is that the recent addition of the output interface (oif) to destination lookups led to unintended comparisons with the next-hop output interface (nh_oif) when the flow structure had the oif set. This caused issues in the Virtual Tunnel Interface (VTI) use case, as it incorrectly filtered out valid routes based on the output interface comparison, disrupting the expected behavior of the networking stack.

Here is the patch:
 /* should be called with rcu_read_lock */
 int fib_table_lookup(struct fib_table *tb, const struct flowi4 *flp,
 		     struct fib_result *res, int fib_flags)
 {
 	struct trie *t = (struct trie *) tb->tb_data;
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 	struct trie_use_stats __percpu *stats = t->stats;
 #endif
 	const t_key key = ntohl(flp->daddr);
 	struct key_vector *n, *pn;
 	struct fib_alias *fa;
 	unsigned long index;
 	t_key cindex;

 	trace_fib_table_lookup(tb->tb_id, flp);

 	pn = t->kv;
 	cindex = 0;

 	n = get_child_rcu(pn, cindex);
 	if (!n)
 		return -EAGAIN;

 #ifdef CONFIG_IP_FIB_TRIE_STATS
 	this_cpu_inc(stats->gets);
 #endif

 	/* Step 1: Travel to the longest prefix match in the trie */
 	for (;;) {
 		index = get_cindex(key, n);

 		/* This bit of code is a bit tricky but it combines multiple
 		 * checks into a single check.  The prefix consists of the
 		 * prefix plus zeros for the "bits" in the prefix. The index
 		 * is the difference between the key and this value.  From
 		 * this we can actually derive several pieces of data.
 		 *   if (index >= (1ul << bits))
 		 *     we have a mismatch in skip bits and failed
 		 *   else
 		 *     we know the value is cindex
 		 *
 		 * This check is safe even if bits == KEYLENGTH due to the
 		 * fact that we can only allocate a node with 32 bits if a
 		 * long is greater than 32 bits.
 		 */
 		if (index >= (1ul << n->bits))
 			break;

 		/* we have found a leaf. Prefixes have already been compared */
 		if (IS_LEAF(n))
 			goto found;

 		/* only record pn and cindex if we are going to be chopping
 		 * bits later.  Otherwise we are just wasting cycles.
 		 */
 		if (n->slen > n->pos) {
 			pn = n;
 			cindex = index;
 		}

 		n = get_child_rcu(n, index);
 		if (unlikely(!n))
 			goto backtrace;
 	}

 	/* Step 2: Sort out leaves and begin backtracing for longest prefix */
 	for (;;) {
 		/* record the pointer where our next node pointer is stored */
 		struct key_vector __rcu **cptr = n->tnode;

 		/* This test verifies that none of the bits that differ
 		 * between the key and the prefix exist in the region of
 		 * the lsb and higher in the prefix.
 		 */
 		if (unlikely(prefix_mismatch(key, n)) || (n->slen == n->pos))
 			goto backtrace;

 		/* exit out and process leaf */
 		if (unlikely(IS_LEAF(n)))
 			break;

 		/* Don't bother recording parent info.  Since we are in
 		 * prefix match mode we will have to come back to wherever
 		 * we started this traversal anyway
 		 */

 		while ((n = rcu_dereference(*cptr)) == NULL) {
 backtrace:
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 			if (!n)
 				this_cpu_inc(stats->null_node_hit);
 #endif
 			/* If we are at cindex 0 there are no more bits for
 			 * us to strip at this level so we must ascend back
 			 * up one level to see if there are any more bits to
 			 * be stripped there.
 			 */
 			while (!cindex) {
 				t_key pkey = pn->key;

 				/* If we don't have a parent then there is
 				 * nothing for us to do as we do not have any
 				 * further nodes to parse.
 				 */
 				if (IS_TRIE(pn))
 					return -EAGAIN;
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 				this_cpu_inc(stats->backtrack);
 #endif
 				/* Get Child's index */
 				pn = node_parent_rcu(pn);
 				cindex = get_index(pkey, pn);
 			}

 			/* strip the least significant bit from the cindex */
 			cindex &= cindex - 1;

 			/* grab pointer for next child node */
 			cptr = &pn->tnode[cindex];
 		}
 	}

 found:
 	/* this line carries forward the xor from earlier in the function */
 	index = key ^ n->key;

 	/* Step 3: Process the leaf, if that fails fall back to backtracing */
 	hlist_for_each_entry_rcu(fa, &n->leaf, fa_list) {
 		struct fib_info *fi = fa->fa_info;
 		int nhsel, err;

 		if ((index >= (1ul << fa->fa_slen)) &&
 		    ((BITS_PER_LONG > KEYLENGTH) || (fa->fa_slen != KEYLENGTH)))
 			continue;
 		if (fa->fa_tos && fa->fa_tos != flp->flowi4_tos)
 			continue;
 		if (fi->fib_dead)
 			continue;
 		if (fa->fa_info->fib_scope < flp->flowi4_scope)
 			continue;
 		fib_alias_accessed(fa);
 		err = fib_props[fa->fa_type].error;
 		if (unlikely(err < 0)) {
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 			this_cpu_inc(stats->semantic_match_passed);
 #endif
 			return err;
 		}
 		if (fi->fib_flags & RTNH_F_DEAD)
 			continue;
 		for (nhsel = 0; nhsel < fi->fib_nhs; nhsel++) {
 			const struct fib_nh *nh = &fi->fib_nh[nhsel];
 			struct in_device *in_dev = __in_dev_get_rcu(nh->nh_dev);

 			if (nh->nh_flags & RTNH_F_DEAD)
 				continue;
 			if (in_dev &&
 			    IN_DEV_IGNORE_ROUTES_WITH_LINKDOWN(in_dev) &&
 			    nh->nh_flags & RTNH_F_LINKDOWN &&
 			    !(fib_flags & FIB_LOOKUP_IGNORE_LINKSTATE))
 				continue;
-			if (!(flp->flowi4_flags & FLOWI_FLAG_VRFSRC)) {
+			if (!(flp->flowi4_flags & FLOWI_FLAG_SKIP_NH_OIF)) {
 				if (flp->flowi4_oif &&
 				    flp->flowi4_oif != nh->nh_oif)
 					continue;
 			}

 			if (!(fib_flags & FIB_LOOKUP_NOREF))
 				atomic_inc(&fi->fib_clntref);

 			res->prefixlen = KEYLENGTH - fa->fa_slen;
 			res->nh_sel = nhsel;
 			res->type = fa->fa_type;
 			res->scope = fi->fib_scope;
 			res->fi = fi;
 			res->table = tb;
 			res->fa_head = &n->leaf;
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 			this_cpu_inc(stats->semantic_match_passed);
 #endif
 			trace_fib_table_lookup_nh(nh);

 			return err;
 		}
 	}
 #ifdef CONFIG_IP_FIB_TRIE_STATS
 	this_cpu_inc(stats->semantic_match_miss);
 #endif
 	goto backtrace;
 }
 EXPORT_SYMBOL_GPL(fib_table_lookup);


